def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = []
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            objects.append((color, cells))

    # Objects settle from right to left; each slides right until blocked by
    # the boundary or an object that has already settled.
    objects.sort(key=lambda obj: max(c for _, c in obj[1]), reverse=True)
    occupied = set()
    placed = []
    for color, cells in objects:
        shift = 0
        while True:
            candidate = {(r, c + shift + 1) for r, c in cells}
            if any(c >= w for _, c in candidate) or candidate & occupied:
                break
            shift += 1
        moved = [(r, c + shift) for r, c in cells]
        occupied.update(moved)
        placed.extend((r, c, color) for r, c in moved)
    out = [[0] * w for _ in range(h)]
    for r, c, color in placed:
